import { readFileSync } from "node:fs";
import { expect, test, type Page } from "@playwright/test";

const ASSISTANT = "hass_ga_manual_ui";
const ENTITY = "input_boolean.e2e_switch";
const NAME = "E2E test switch";
const EXPOSE_URL = `/config/voice-assistants/expose?assistants=${ASSISTANT}`;

interface E2EHass {
  connected: boolean;
  entities: object;
  connection: {
    suspendReconnectUntil(promise: Promise<void>): void;
    suspend(): void;
  };
}

interface IntegrationConfig {
  enabled: boolean;
  report_state: boolean;
  secure_devices_pin: string;
}

// Generated by the disposable HA server; never checked in or served over HTTP.
function serverState(): { auth: { access_token: string }; entry_id: string } {
  return JSON.parse(readFileSync(".e2e/state.json", "utf8"));
}

// Catch render failures and the two compatibility warnings reported in #30.
function collectFrontendFailures(page: Page): string[] {
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  page.on("console", (message) => {
    if (/_availableAssistants getter not found|cloud-discover\.render not found/.test(message.text())) {
      errors.push(message.text());
    }
  });
  return errors;
}

// A separate real client can change exposure while the tested browser sleeps.
async function callBackend<T>(message: Record<string, unknown>): Promise<T> {
  const socket = new WebSocket("ws://127.0.0.1:18096/api/websocket");
  try {
    return await new Promise<T>((resolve, reject) => {
      socket.addEventListener("error", () => reject(new Error("Backend WebSocket failed")));
      socket.addEventListener("message", (event) => {
        const response = JSON.parse(String(event.data));
        if (response.type === "auth_required") {
          socket.send(JSON.stringify({ type: "auth", access_token: serverState().auth.access_token }));
        } else if (response.type === "auth_ok") {
          socket.send(JSON.stringify({ ...message, id: 1 }));
        } else if (response.type === "auth_invalid") {
          reject(new Error(response.message));
        } else if (response.type === "result") {
          if (response.success) resolve(response.result as T);
          else reject(new Error(JSON.stringify(response.error)));
        }
      });
    });
  } finally {
    socket.close();
  }
}

// Read the integration's persisted settings through its real WS bridge.
function integrationConfig(): Promise<IntegrationConfig> {
  return callBackend({ type: `${ASSISTANT}/get_config`, entry_id: serverState().entry_id });
}

// Use the native dialog and save button, then check real backend storage.
async function exposeThroughUI(page: Page): Promise<void> {
  await page.locator("ha-config-voice-assistants-expose ha-button[slot=fab]").click();
  const dialog = page.locator("dialog-expose-entity");
  await expect(dialog.getByRole("dialog")).toBeVisible();
  await expect(dialog.locator("ha-dialog")).toHaveAttribute("header-subtitle", /Google Assistant \(Manual\)/);
  await dialog.locator("ha-input-search input").fill(NAME);
  await dialog.locator("ha-check-list-item").filter({ hasText: NAME }).click();
  await dialog.locator("ha-dialog-footer ha-button[slot=primaryAction]").click();
  await expect(dialog.getByRole("dialog")).not.toBeVisible();
  await expect.poll(async () => {
    const result = await callBackend<{ exposed_entities: Record<string, Record<string, boolean>> }>({
      type: "homeassistant/expose_entity/list",
    });
    return result.exposed_entities[ENTITY]?.[ASSISTANT];
  }).toBe(true);
  await expect(page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true })).toBeVisible();
}

test.beforeEach(async ({ context }) => {
  await context.addInitScript((auth) => {
    if (location.origin !== "http://127.0.0.1:18096") return;
    localStorage.setItem("hassTokens", JSON.stringify(auth));
    localStorage.setItem("selectedLanguage", JSON.stringify("en"));
  }, serverState().auth);
  if (!(await integrationConfig()).enabled) {
    await callBackend({ type: `${ASSISTANT}/enable`, entry_id: serverState().entry_id });
  }
  await callBackend({
    type: `${ASSISTANT}/update_config`,
    entry_id: serverState().entry_id,
    data: { report_state: false, secure_devices_pin: "" },
  });
  await callBackend({
    type: "homeassistant/expose_new_entities/set",
    assistant: ASSISTANT,
    expose_new: false,
  });
  await callBackend({
    type: "homeassistant/expose_entity",
    assistants: [ASSISTANT, "conversation"],
    entity_ids: [ENTITY],
    should_expose: false,
  });
});

test("native exposure dialog saves, survives reload, and works after idle reconnect", async ({ page }) => {
  const errors = collectFrontendFailures(page);
  await page.goto(EXPOSE_URL);
  await exposeThroughUI(page);
  const server = serverState();
  const reload = await page.request.post(`/api/config/config_entries/entry/${server.entry_id}/reload`, {
    headers: { Authorization: `Bearer ${server.auth.access_token}` },
  });
  expect(reload.ok()).toBe(true);
  await page.reload();
  await expect(page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true })).toBeVisible();

  // Use HA's own suspension mechanism, rather than mocking its connected flag.
  await page.evaluate(() => {
    const hass = (document.querySelector("home-assistant") as HTMLElement & { hass: E2EHass }).hass;
    const state = window as unknown as { resumeE2E?: () => void; entitiesBeforeIdle?: object };
    state.entitiesBeforeIdle = hass.entities;
    hass.connection.suspendReconnectUntil(new Promise<void>((resolve) => { state.resumeE2E = resolve; }));
    hass.connection.suspend();
  });
  await page.waitForFunction(() =>
    !(document.querySelector("home-assistant") as HTMLElement & { hass: E2EHass }).hass.connected,
  );
  await callBackend({
    type: "homeassistant/expose_entity",
    assistants: [ASSISTANT],
    entity_ids: [ENTITY],
    should_expose: false,
  });
  // The sleeping browser still has the old snapshot until reconnect.
  await expect(page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true })).toBeVisible();
  await page.evaluate(() => (window as unknown as { resumeE2E: () => void }).resumeE2E());
  await page.waitForFunction(() =>
    (document.querySelector("home-assistant") as HTMLElement & { hass: E2EHass }).hass.connected,
  );
  await expect(page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true })).toHaveCount(0);
  expect(await page.evaluate(() => {
    const hass = (document.querySelector("home-assistant") as HTMLElement & { hass: E2EHass }).hass;
    return hass.entities === (window as unknown as { entitiesBeforeIdle: object }).entitiesBeforeIdle;
  })).toBe(true);
  await exposeThroughUI(page);
  expect(errors).toEqual([]);
});

test("native entity dialog keeps manual-only exposure and refreshes both toggle types", async ({ page }) => {
  const errors = collectFrontendFailures(page);
  await callBackend({
    type: "homeassistant/expose_entity",
    assistants: [ASSISTANT],
    entity_ids: [ENTITY],
    should_expose: true,
  });
  await page.goto(EXPOSE_URL);
  await page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true }).click();
  const dialog = page.locator("dialog-voice-settings");
  await expect(dialog.getByRole("dialog")).toBeVisible();
  const settings = dialog.locator("entity-voice-settings");
  const master = settings.locator("ha-switch").first();
  const manual = settings.locator("ha-row-item").filter({ hasText: "Google Assistant (Manual)" }).locator("ha-switch");

  // Only manual GA is exposed: HA's master switch must still be checked and
  // its native per-assistant row must remain visible without a Cloud account.
  await expect(master).toHaveJSProperty("checked", true);
  await expect(manual).toBeVisible();
  await expect(manual).toHaveJSProperty("checked", true);
  await manual.click();
  await expect(master).toHaveJSProperty("checked", false);
  await expect.poll(async () => {
    const result = await callBackend<{ exposed_entities: Record<string, unknown> }>({ type: "homeassistant/expose_entity/list" });
    return result.exposed_entities[ENTITY];
  }).toBeUndefined();

  // Native master writes, entry refetches, and the dialog's exposure snapshot
  // must agree immediately, without closing and reopening the dialog.
  await master.click();
  await expect(master).toHaveJSProperty("checked", true);
  await expect(manual).toHaveJSProperty("checked", true);
  await expect.poll(async () => {
    const result = await callBackend<{ exposed_entities: Record<string, unknown> }>({ type: "homeassistant/expose_entity/list" });
    return result.exposed_entities[ENTITY];
  }).toEqual({ conversation: true, [ASSISTANT]: true });
  await master.click();
  await expect(master).toHaveJSProperty("checked", false);
  await expect(page.locator("ha-config-voice-assistants-expose").getByText(NAME, { exact: true })).toHaveCount(0);
  expect(errors).toEqual([]);
});

test("the configured Cloud promotion and dashboard entry are hidden", async ({ page }) => {
  const errors = collectFrontendFailures(page);
  await page.goto("/config/voice-assistants/assistants");
  await expect(page.locator("[data-ga-manual-card]")).toBeVisible();
  await expect(page.locator("cloud-discover")).toBeAttached();
  await expect(page.locator("cloud-discover ha-card")).toHaveCount(0);
  await page.goto("/config");
  await expect(page.locator('ha-config-dashboard a[href="/config/integrations"]')).toBeVisible();
  await expect(page.locator('ha-config-dashboard a[href="/config/cloud"]')).toHaveCount(0);
  expect(errors).toEqual([]);
});

test("assistant card renders its controls and stays unique across toggles and SPA navigation", async ({ page }) => {
  const errors = collectFrontendFailures(page);
  await page.goto("/config/voice-assistants/assistants");
  const card = page.locator("ha-card[data-ga-manual-card]");
  await expect(card).toHaveCount(1);
  await expect(card).toHaveAttribute("outlined", "");
  await expect(card.locator("h1.card-header")).toContainText("Google Assistant (Manual)");
  const icon = card.locator("img[data-ga-manual]");
  await expect(icon).toHaveAttribute("src", /\/hass_ga_manual_ui\/brand\/icon\.png$/);
  await expect.poll(() => icon.evaluate((image: HTMLImageElement) => image.naturalWidth)).toBeGreaterThan(0);
  await expect(card.locator(".card-content p")).not.toBeEmpty();
  await expect(card.locator("ha-md-list-item")).toHaveCount(3);
  await expect(card.locator("ha-input")).toBeVisible();
  await expect(card.locator("[data-ga-options-yaml]")).toHaveCount(0);

  const globalSwitch = card.locator(".card-header ha-switch");
  const exposeNew = card.locator(".card-content ha-switch").first();
  await expect(exposeNew).toHaveJSProperty("checked", false);
  await expect(globalSwitch).toHaveJSProperty("checked", true);
  await globalSwitch.click();
  await expect.poll(async () => (await integrationConfig()).enabled).toBe(false);
  await expect(card.locator("[data-ga-row]:visible")).toHaveCount(0);
  await globalSwitch.click();
  await expect.poll(async () => (await integrationConfig()).enabled).toBe(true);
  await expect(card.locator("ha-input")).toBeVisible();
  await expect(globalSwitch).toHaveJSProperty("checked", true);
  await expect(exposeNew).toHaveJSProperty("checked", false);

  // Use HA's tab navigation so its cached page and our lifecycle hooks are
  // exercised together; repeatedly evaluating a mocked bundle cannot do this.
  for (let visit = 0; visit < 2; visit++) {
    await page.getByRole("tab", { name: "Expose", exact: true }).click();
    await expect(page.locator("ha-config-voice-assistants-expose ha-button[slot=fab]")).toBeVisible();
    await page.getByRole("tab", { name: "Assistants", exact: true }).click();
    await expect(card).toHaveCount(1);
    await expect(globalSwitch).toHaveJSProperty("checked", true);
  }
  await page.reload();
  await expect(card).toHaveCount(1);
  await expect(card.locator("ha-input")).toBeVisible();
  expect(errors).toEqual([]);
});

test("native options dialog exports YAML and applies only confirmed imports", async ({ page }) => {
  const errors = collectFrontendFailures(page);
  const nativeDialogs: string[] = [];
  page.on("dialog", (dialog) => { nativeDialogs.push(dialog.type()); void dialog.dismiss(); });
  await callBackend({
    type: "homeassistant/expose_entity", assistants: [ASSISTANT], entity_ids: [ENTITY], should_expose: true,
  });
  await page.goto(`/config/integrations/integration/${ASSISTANT}`);
  await page.locator(`ha-config-entry-row[data-entry-id="${serverState().entry_id}"]`).getByRole("button", { name: "Configure", exact: true }).click();
  const options = page.locator("dialog-data-entry-flow");
  await expect(options.getByRole("dialog")).toBeVisible();
  const exportButton = options.locator("[data-ga-options-yaml=export]");
  const importButton = options.locator("[data-ga-options-yaml=import]");
  await expect(exportButton).toHaveText("Export YAML");
  await expect(importButton).toHaveText("Import YAML");

  const expected = await callBackend<{ yaml: string }>({ type: `${ASSISTANT}/export_config`, entry_id: serverState().entry_id });
  const [download] = await Promise.all([page.waitForEvent("download"), exportButton.click()]);
  expect(download.suggestedFilename()).toMatch(/e2e-test-project.*\.yaml$/);
  const yaml = readFileSync((await download.path())!, "utf8");
  expect(yaml).toBe(expected.yaml);
  expect(yaml).toContain("google_assistant:");
  expect(yaml).toContain(`${ENTITY}:`);

  const imported = `google_assistant:\n  report_state: false\n  secure_devices_pin: "2468"\n  expose_by_default: false\n  entity_config:\n    ${ENTITY}:\n      expose: false\n      aliases:\n        - E2E imported alias\n`;
  for (const confirm of [false, true]) {
    const [picker] = await Promise.all([page.waitForEvent("filechooser"), importButton.click()]);
    await picker.setFiles({ name: "settings.yaml", mimeType: "text/yaml", buffer: Buffer.from(imported) });
    const confirmation = page.locator("[data-ga-confirm-dialog]");
    await expect(confirmation).toBeVisible();
    await expect(confirmation.locator("ha-card")).toBeVisible();
    await confirmation.locator(confirm ? "[data-ga-confirm]" : "[data-ga-cancel]").click();
    await expect(confirmation).toHaveCount(0);
    await expect(page.locator('input[type="file"]')).toHaveCount(0);
    await expect.poll(async () => (await integrationConfig()).secure_devices_pin).toBe(confirm ? "2468" : "");
    const exposures = await callBackend<{ exposed_entities: Record<string, unknown> }>({ type: "homeassistant/expose_entity/list" });
    expect(exposures.exposed_entities[ENTITY]).toEqual(confirm ? undefined : { [ASSISTANT]: true });
  }
  const entity = await callBackend<{ aliases: (string | null)[] }>({ type: "config/entity_registry/get", entity_id: ENTITY });
  expect(entity.aliases).toContain("E2E imported alias");
  await page.goto("/config/voice-assistants/assistants");
  await expect(page.locator("[data-ga-manual-card] ha-input")).toHaveJSProperty("value", "2468");
  await expect(page.locator("[data-ga-count]")).toContainText("0");
  expect(nativeDialogs).toEqual([]);
  expect(errors).toEqual([]);
});
